command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="ce51aa2804902990776071293990dad48a4ed1f1"
$candidate="384ae72d69d1f55ceb98cf3595cb62478f418418"
$branch="work/search-content-regex-20261007"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "content regex preflight fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before content regex preflight"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "content regex candidate moved"}
$temp=Join-Path $env:RUNNER_TEMP ("fly-content-regex-fast-"+$env:GITHUB_RUN_ID)
if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
try{
  & git worktree add --detach $temp $candidate
  if($LASTEXITCODE -ne 0){throw "content regex worktree add failed"}
  Set-Location -LiteralPath $temp
  & git diff --check ($main+"..."+$candidate)
  if($LASTEXITCODE -ne 0){throw "content regex diff check failed"}
  & python -X utf8 tools\winui\run_checks.py fast --before $main --head $candidate
  if($LASTEXITCODE -ne 0){throw "content regex FAST checks failed"}
  & cmd /c tests\winui\m19\build.cmd Debug
  if($LASTEXITCODE -ne 0){throw "content regex M19 Debug build failed"}
  $env:FLY_M19_CONFIG="Debug"
  & python -X utf8 tests\winui\m19\test_native.py
  if($LASTEXITCODE -ne 0){throw "content regex M19 Debug native failed"}
  Write-Host "CONTENT_REGEX_DIFF_CHECK=PASS"
  Write-Host "CONTENT_REGEX_FAST=PASS"
  Write-Host "CONTENT_REGEX_M19_DEBUG=PASS"
}finally{
  Set-Location -LiteralPath $repo
  if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp}
  & git worktree prune
}
